     "summary": "景区整治“野拍”，真的是为了“赶摆摊摄影师”吗？最近广州沙面的整治行动，给出了不一样的答案。作为广州知名文旅地标，沙面凭借欧式建筑群常年客流火爆，也催生了热门的“野拍”服务。据了解，有三十多名摄影师在景区接单，平价旅拍既满足游客打卡需求，也成为不少人的灵活就业渠道。那为什么突然整顿？问题不在于拍照服务本身，而在于部分摄影师反复纠缠游客、强行揽客，严重影响游览体验，引发大量投诉。</p...",
